package com.madhukar.upisplitter.controller;
import com.madhukar.upisplitter.dto.*; import com.madhukar.upisplitter.dto.AuthDtos.*; import com.madhukar.upisplitter.service.*; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService auth;public AuthController(AuthService a){auth=a;}@PostMapping("/register") public ApiDtos.ApiResponse<AuthResponse> register(@Valid @RequestBody RegisterRequest r){return ApiResponseFactory.ok("Registration successful",auth.register(r));}@PostMapping("/login") public ApiDtos.ApiResponse<AuthResponse> login(@Valid @RequestBody LoginRequest r){return ApiResponseFactory.ok("Login successful",auth.login(r));}@GetMapping("/me") public ApiDtos.ApiResponse<MeResponse> me(Authentication a){var u=auth.byId((String)a.getDetails());return ApiResponseFactory.ok("Authenticated",new MeResponse(u.getId(),u.getName(),u.getEmail(),u.getRole().name()));}}
